using System.IO;
using System.Diagnostics;
using System.Text;
using System.Text.Json;
using System.Security.Cryptography;
using System.Runtime.InteropServices;
using Microsoft.VisualBasic.FileIO;
namespace DiskLens;
public sealed class Store { public static string? DefaultHome {get;set;}
 public string Home {get;}
 public IReadOnlyList<string> HistoryHomes {get;}
 public Store(string? home=null,IEnumerable<string>? additionalHistoryHomes=null){
  var local=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
  Home=home??DefaultHome??System.IO.Path.Combine(local,"DiskLens.Wpf");Directory.CreateDirectory(Home);
  var locations=new List<string>{Home};
  if(additionalHistoryHomes!=null)locations.AddRange(additionalHistoryHomes);
  else if(home==null&&DefaultHome==null){
   // Desktop launches do not see the app-data overlay inherited by Codex-launched scans.
   var packages=System.IO.Path.Combine(local,"Packages");
   if(Directory.Exists(packages))foreach(var package in Directory.EnumerateDirectories(packages,"OpenAI.Codex_*")){
    var redirected=System.IO.Path.Combine(package,"LocalCache","Local","DiskLens.Wpf");
    if(Directory.Exists(redirected))locations.Add(redirected);
   }
  }
  HistoryHomes=locations.Select(System.IO.Path.GetFullPath).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();
 }
 public string HistoryWarning {get;private set;}="";
 public List<ScanInfo> History(){
  var result=new List<ScanInfo>();var failures=new List<string>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  foreach(var location in HistoryHomes.Where(Directory.Exists))foreach(var p in Directory.EnumerateFiles(location,"*.json")){
   if(System.IO.Path.GetFileName(p).Equals("settings.json",StringComparison.OrdinalIgnoreCase))continue;
   // Reports and settings are not snapshot metadata, even when they contain JSON.
   try{
    var json=File.ReadAllText(p);using var document=JsonDocument.Parse(json);
    if(document.RootElement.ValueKind!=JsonValueKind.Object||!document.RootElement.TryGetProperty("Id",out _))continue;
    var saved=JsonSerializer.Deserialize<ScanInfo>(json);
    if(saved==null||saved.Id!=System.IO.Path.GetFileNameWithoutExtension(p)||string.IsNullOrWhiteSpace(saved.Root)||!DateTimeOffset.TryParse(saved.Date,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.AssumeUniversal,out _))throw new InvalidDataException("Invalid snapshot metadata");
    if(File.Exists(System.IO.Path.Combine(location,saved.Id+".db"))){if(seen.Add(saved.Id))result.Add(saved);}
    else failures.Add(System.IO.Path.GetFileName(p)+": completed index is missing");
   }catch(Exception e)when(e is IOException or UnauthorizedAccessException or JsonException or ArgumentException){failures.Add(System.IO.Path.GetFileName(p)+": "+e.Message);}
  }
  HistoryWarning=failures.Count==0?"":$"{failures.Count} saved snapshot(s) could not be loaded. "+string.Join("; ",failures);
  return result.OrderByDescending(x=>DateTimeOffset.Parse(x.Date,System.Globalization.CultureInfo.InvariantCulture)).ToList();
 }
 public string LastMaintenanceWarning{get;private set;}="";
 public string PathFor(ScanInfo s)=>HistoryHomes.Select(location=>System.IO.Path.Combine(location,s.Id+".db")).FirstOrDefault(File.Exists)??System.IO.Path.Combine(Home,s.Id+".db");
 public void DeleteSnapshot(ScanInfo s){foreach(var location in HistoryHomes){File.Delete(System.IO.Path.Combine(location,s.Id+".db"));File.Delete(System.IO.Path.Combine(location,s.Id+".json"));}}
 public void Commit(ScanInfo s,string pending,int retention){LastMaintenanceWarning="";File.Move(pending,PathFor(s));var temp=System.IO.Path.Combine(Home,s.Id+".tmp");using(var stream=new FileStream(temp,FileMode.Create,FileAccess.Write,FileShare.None)){using(var writer=new StreamWriter(stream,Encoding.UTF8,1024,true)){writer.Write(JsonSerializer.Serialize(s));writer.Flush();}stream.Flush(true);}File.Move(temp,System.IO.Path.Combine(Home,s.Id+".json"));foreach(var old in History().Where(x=>x.Root.Equals(s.Root,StringComparison.OrdinalIgnoreCase)).Skip(Math.Clamp(retention,1,365))){try{DeleteSnapshot(old);}catch(Exception e)when(e is IOException or UnauthorizedAccessException){LastMaintenanceWarning="Some older snapshots could not be pruned: "+e.Message;}}}
 public List<Entry> Search(ScanInfo s,string patterns,long min,long max,string mode,int page=0,CancellationToken ct=default){
  ct.ThrowIfCancellationRequested();using var db=new Db(PathFor(s));using var cancellation=ct.Register(db.Interrupt);var matches=Rules.Matcher(patterns);bool filtering=!string.IsNullOrWhiteSpace(patterns);long offset=(long)Math.Max(0,page)*500,skipped=0;long now=DateTime.UtcNow.Ticks;var items=new List<Entry>(500);
  var where=$"size>={Math.Max(0,min)} AND size<={(max<=0?long.MaxValue:max)} AND {SearchCandidates.Where(patterns)}";
  if(mode=="Old files")where+=$" AND modified>0 AND modified<={now-TimeSpan.FromDays(365).Ticks}";
  if(mode=="Recent files")where+=$" AND modified>={now-TimeSpan.FromDays(30).Ticks}";
  try{foreach(var r in db.Query($"SELECT path,size,modified FROM files WHERE {where} ORDER BY size DESC")){
   ct.ThrowIfCancellationRequested();if(filtering&&!matches(r[0]))continue;var modified=long.Parse(r[2]);
   if(mode=="Installers"&&!Rules.Installer(r[0]))continue;
   if(mode=="Old files"&&(modified==0||now-modified<TimeSpan.FromDays(365).Ticks))continue;
   if(mode=="Recent files"&&now-modified>TimeSpan.FromDays(30).Ticks)continue;
   string? reason=mode=="Cleanup candidates"?Rules.Explain(r[0],modified):null;if(mode=="Cleanup candidates"&&reason!.Length==0)continue;
   if(skipped++<offset)continue;items.Add(new Entry(r[0],long.Parse(r[1]),modified,"file",reason??Rules.Explain(r[0],modified)));if(items.Count==500)break;
  }return items;}catch{ct.ThrowIfCancellationRequested();throw;}
 }
 public List<Entry> Map(ScanInfo s,string folder){using var db=new Db(PathFor(s));var result=db.Query($"SELECT path,size,modified FROM files WHERE parent={Db.Q(folder)} ORDER BY size DESC LIMIT 100").Select(r=>new Entry(r[0],long.Parse(r[1]),long.Parse(r[2]),"file")).ToList();foreach(var r in db.Query($"SELECT path,size FROM folders WHERE parent={Db.Q(folder)} ORDER BY size DESC LIMIT 150"))result.Add(new Entry(r[0],long.Parse(r[1]),0,"folder"));result=result.OrderByDescending(x=>x.Size).Take(150).ToList();var total=long.Parse(db.Query($"SELECT size FROM folders WHERE path={Db.Q(folder)}").FirstOrDefault()?[0]??"0");var omitted=total-result.Sum(x=>x.Size);if(omitted>0)result.Add(new Entry("Other indexed items",omitted,0,"summary","Items outside the 150 largest map tiles; use search for all files"));return result;}
 public List<Entry> Insights(ScanInfo s){using var db=new Db(PathFor(s));return db.Query("SELECT extension,SUM(size),COUNT(*) FROM files GROUP BY extension ORDER BY SUM(size) DESC").Select(r=>new Entry(r[0].Length==0?"(no extension)":r[0],long.Parse(r[1]),0,"summary",r[2]+" files")).ToList();}
 public List<Entry> Breakdown(ScanInfo s,bool documents=false){using var db=new Db(PathFor(s));var groups=documents?new Dictionary<string,string[]>{["PDF"]=[".pdf"],["Word"]=[".doc",".docx"],["Excel"]=[".xls",".xlsx"],["PowerPoint"]=[".ppt",".pptx"],["Text"]=[".txt"],["Email"]=[".pst"]}:new Dictionary<string,string[]>{["Video"]=[".mp4",".mov",".mkv",".avi",".webm"],["Images"]=[".png",".jpg",".jpeg",".gif",".webp",".tiff",".raw"],["Archives"]=[".zip",".7z",".rar",".iso",".gz",".tar"],["Code"]=[".js",".jsx",".ts",".tsx",".cs",".java",".py",".cache"],["Documents"]=[".pdf",".doc",".docx",".xls",".xlsx",".ppt",".pptx",".txt",".pst"],["Applications"]=[".exe",".dll",".msi",".msix",".appx",".appxbundle",".vhdx",".db",".bin"]};var expression="CASE "+string.Join(" ",groups.Select(g=>$"WHEN extension IN ({string.Join(',',g.Value.Select(Db.Q))}) THEN {Db.Q(g.Key)}"))+" ELSE 'Other' END";return db.Query($"SELECT {expression},SUM(size),COUNT(*) FROM files GROUP BY {expression} ORDER BY SUM(size) DESC").Where(r=>!documents||r[0]!="Other").Select(r=>new Entry(r[0],long.Parse(r[1]),0,"summary",r[2]+" files")).ToList();}
 public List<Entry> Growth(ScanInfo current,ScanInfo previous,bool folders){if(!folders){var old=Breakdown(previous).ToDictionary(e=>e.Path,e=>e.Size);return Breakdown(current).Select(e=>e with{Detail=$"Change from previous scan: {e.Size-old.GetValueOrDefault(e.Path):+0;-0;0} bytes"}).ToList();}using var db=new Db(PathFor(current));db.Exec($"ATTACH DATABASE {Db.Q(PathFor(previous))} AS old;");return db.Query($"SELECT n.path,n.size,n.size-COALESCE(o.size,0) FROM folders n LEFT JOIN old.folders o ON n.path=o.path WHERE n.parent={Db.Q(current.Root)} UNION ALL SELECT o.path,0,-o.size FROM old.folders o LEFT JOIN folders n ON n.path=o.path WHERE o.parent={Db.Q(previous.Root)} AND n.path IS NULL ORDER BY 2 DESC LIMIT 500").Select(r=>new Entry(r[0],long.Parse(r[1]),0,"summary","Change from previous scan: "+r[2]+" bytes")).ToList();} public List<Entry> Issues(ScanInfo s){using var db=new Db(PathFor(s));return db.Query("SELECT path,detail FROM issues LIMIT 500").Select(r=>new Entry(r[0],0,0,"issue",r[1])).ToList();}
 public List<Entry> Changes(ScanInfo current,ScanInfo previous){using var db=new Db(PathFor(current));db.Exec($"ATTACH DATABASE {Db.Q(PathFor(previous))} AS old;");return db.Query("SELECT n.path,n.size,n.modified,CASE WHEN o.path IS NULL THEN 'Added' WHEN n.size>o.size THEN 'Grown by '||(n.size-o.size)||' bytes' ELSE 'Shrunk by '||(o.size-n.size)||' bytes' END FROM files n LEFT JOIN old.files o ON n.path=o.path WHERE o.path IS NULL OR n.size!=o.size UNION ALL SELECT o.path,o.size,o.modified,'Removed or inaccessible/excluded in current scan' FROM old.files o LEFT JOIN files n ON n.path=o.path WHERE n.path IS NULL ORDER BY 2 DESC LIMIT 500").Select(r=>new Entry(r[0],long.Parse(r[1]),long.Parse(r[2]),"change",r[3])).ToList();}
 public IEnumerable<Entry> All(ScanInfo s){using var db=new Db(PathFor(s));foreach(var r in db.Query("SELECT path,size,modified FROM files ORDER BY path"))yield return new Entry(r[0],long.Parse(r[1]),long.Parse(r[2]),"file",Rules.Explain(r[0],long.Parse(r[2])));}
}
public static class Actions {
 internal static Action<string>? OpenFolderTestOverride;
 public static void OpenFolder(string p){
  if(Directory.Exists(p)){if(Store.DefaultHome!=null&&OpenFolderTestOverride!=null){OpenFolderTestOverride(p);return;}Process.Start(new ProcessStartInfo("explorer.exe",$"\"{p}\""){UseShellExecute=true});}
  else if(File.Exists(p))Reveal(p);
  else throw new FileNotFoundException("This item is no longer available on disk. Connect its drive or select another item.",p);
 }
 internal static Action<string>? RevealTestOverride; public static void Reveal(string p){if(Store.DefaultHome!=null&&RevealTestOverride!=null){RevealTestOverride(p);return;}Process.Start(new ProcessStartInfo("explorer.exe",$"/select,\"{p}\""){UseShellExecute=true});}
 public static void Recycle(Entry e){if(e.Kind!="file")throw new IOException("Only individual indexed files may be recycled.");var f=new FileInfo(e.Path);if(!f.Exists||f.Length!=e.Size||f.LastWriteTimeUtc.Ticks!=e.Modified)throw new IOException("The file changed since scanning. Rescan before cleanup.");for(var parent=f.Directory;parent!=null;parent=parent.Parent)if((parent.Attributes&FileAttributes.ReparsePoint)!=0)throw new IOException("The file now has a reparse-point ancestor. Rescan before cleanup.");var protectedRoots=new[]{Environment.GetFolderPath(Environment.SpecialFolder.Windows),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86)};if(protectedRoots.Any(p=>p.Length>0&&e.Path.StartsWith(p.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))||(f.Attributes&(FileAttributes.System|FileAttributes.ReparsePoint))!=0)throw new IOException("System, installed-program and reparse-point files are protected.");FileSystem.DeleteFile(e.Path,UIOption.AllDialogs,RecycleOption.SendToRecycleBin,UICancelOption.ThrowException);}
 public static void Export(string path,IEnumerable<Entry> entries){using var w=new StreamWriter(path,false,new UTF8Encoding(true));var ext=System.IO.Path.GetExtension(path).ToLowerInvariant();if(ext==".json"){w.Write('[');bool first=true;foreach(var e in entries){if(!first)w.Write(',');w.Write(JsonSerializer.Serialize(e));first=false;}w.Write(']');}else if(ext==".html"){w.Write("<!doctype html><meta charset=utf-8><title>DiskLens report</title><link rel=icon href=\"data:image/png;base64,\"><style>body{font:14px Segoe UI;margin:30px}td{padding:8px;border-bottom:1px solid #ddd;word-break:break-all}</style><h1>DiskLens report</h1><table><tr><th>Path</th><th>Bytes</th><th>Explanation</th><th>Change</th><th>Difference bytes</th></tr>");foreach(var e in entries)w.Write($"<tr><td>{System.Net.WebUtility.HtmlEncode(e.Path)}</td><td>{e.Size}</td><td>{System.Net.WebUtility.HtmlEncode(e.Detail)}</td><td>{System.Net.WebUtility.HtmlEncode(e.Change)}</td><td>{e.Delta}</td></tr>");w.Write("</table>");}else{w.WriteLine("Path,Bytes,ModifiedUtc,Kind,Explanation,Change,DifferenceBytes");string Q(string s)=>"\""+(s.Length>0&&"=+-@".Contains(s[0])?"\u0027"+s:s).Replace("\"","\"\"")+"\"";foreach(var e in entries)w.WriteLine($"{Q(e.Path)},{e.Size},{Q(e.Modified>0?new DateTime(e.Modified,DateTimeKind.Utc).ToString("O"):"")},{Q(e.Kind)},{Q(e.Detail)},{Q(e.Change)},{e.Delta}");}}
}

public record DuplicateMetrics(long Available,long Selected,long Hashed,long Skipped,long BytesHashed,double Milliseconds,bool Limited);
public record HashResult(string Hash,string Identity,string Error="");
public static class Duplicates {
 [StructLayout(LayoutKind.Sequential)] struct Info {public uint Attributes;public System.Runtime.InteropServices.ComTypes.FILETIME Created,Accessed,Written;public uint Volume,SizeHigh,SizeLow,Links,IndexHigh,IndexLow;}
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetFileInformationByHandle(Microsoft.Win32.SafeHandles.SafeFileHandle handle,out Info info);
 public static int HashWorker(){var buffer=new byte[65536];string? line;while((line=Console.ReadLine())!=null){try{var e=JsonSerializer.Deserialize<Entry>(line)!;var f=new FileInfo(e.Path);if(f.Length!=e.Size||f.LastWriteTimeUtc.Ticks!=e.Modified)throw new IOException("Changed since scan");using var stream=new FileStream(e.Path,FileMode.Open,FileAccess.Read,FileShare.Read,65536,FileOptions.SequentialScan);if(!GetFileInformationByHandle(stream.SafeFileHandle,out var info))throw new IOException("Cannot read file identity");using var hash=IncrementalHash.CreateHash(HashAlgorithmName.SHA256);int n;long read=0;var sw=Stopwatch.StartNew();var last=TimeSpan.Zero;while((n=stream.Read(buffer))>0){hash.AppendData(buffer,0,n);read+=n;if(sw.Elapsed-last>TimeSpan.FromMilliseconds(250)){Console.WriteLine("PROGRESS "+read);last=sw.Elapsed;}}f.Refresh();if(f.Length!=e.Size||f.LastWriteTimeUtc.Ticks!=e.Modified)throw new IOException("Changed during hashing");Console.WriteLine(JsonSerializer.Serialize(new HashResult(Convert.ToHexString(hash.GetHashAndReset()),$"{info.Volume}:{info.IndexHigh}:{info.IndexLow}")));}catch(Exception ex){Console.WriteLine(JsonSerializer.Serialize(new HashResult("","",ex.Message)));}}return 0;}
 public static async Task<List<Entry>> Find(Store store,ScanInfo scan,string filter,long min,long max,IProgress<string> progress,CancellationToken ct,bool installerOnly=false,int ageDays=0,Action<long,long>? summary=null,string category="All",int candidateLimit=0,Action<DuplicateMetrics>? metrics=null){
 var matches=Rules.Matcher(filter);var watch=Stopwatch.StartNew();using var db=new Db(store.PathFor(scan));using var cancellation=ct.Register(db.Interrupt);ct.ThrowIfCancellationRequested();
 db.Exec("CREATE TEMP TABLE eligible(path TEXT,size INTEGER,modified INTEGER); CREATE TEMP TABLE hashes(hash TEXT,identity TEXT UNIQUE,path TEXT,size INTEGER,modified INTEGER); CREATE INDEX temp.hash_index ON hashes(hash,size);");
 var sizeWhere=$"size>={Math.Max(1,min)} AND size<={(max>0?max:long.MaxValue)}";var where=$"{sizeWhere} AND {SearchCandidates.Where(filter)} AND size IN (SELECT size FROM files WHERE {sizeWhere} GROUP BY size HAVING COUNT(*)>1)";if(ageDays>0)where+=$" AND modified<={DateTime.UtcNow.AddDays(-Math.Min(ageDays,365000)).Ticks}";
 progress.Report("Preparing duplicate candidates • applying filters before size grouping");
 using(var insert=db.Prepare("INSERT INTO eligible VALUES(?,?,?)")){db.Exec("BEGIN");int count=0;foreach(var r in db.Query($"SELECT path,size,modified FROM files WHERE {where}")){ct.ThrowIfCancellationRequested();if(filter.Length>0&&!matches(r[0])||installerOnly&&!Rules.Installer(r[0])||category!="All"&&(category=="Installers"?!Rules.Installer(r[0]):Rules.Category(r[0])!=category))continue;insert.Text(1,r[0]);insert.Number(2,long.Parse(r[1]));insert.Number(3,long.Parse(r[2]));insert.Execute();if(++count%1024==0)db.Exec("COMMIT; BEGIN");}db.Exec("COMMIT");}
 db.Exec("CREATE INDEX temp.eligible_size ON eligible(size); CREATE TEMP TABLE duplicate_sizes AS SELECT size FROM eligible GROUP BY size HAVING COUNT(*)>1; CREATE UNIQUE INDEX temp.duplicate_sizes_index ON duplicate_sizes(size);");
 var available=long.Parse(db.Query("SELECT COUNT(*) FROM eligible WHERE size IN (SELECT size FROM duplicate_sizes)").First()[0]);var total=candidateLimit>0?Math.Min(available,candidateLimit):available;bool limited=total<available;var coverage=candidateLimit>0?$"Quick • {total:N0} of {available:N0} candidates":"Full • all "+available.ToString("N0")+" candidates";
 long checkedFiles=0,skipped=0,hashed=0,bytesHashed=0;var lastReport=TimeSpan.Zero;Process? worker=null;
 void Kill(){if(worker==null)return;try{if(!worker.HasExited)worker.Kill(true);}catch{}worker.Dispose();worker=null;}
 void Report(string path){progress.Report($"Verifying SHA-256 • {checkedFiles:N0}/{total:N0} • {(total>0?100d*checkedFiles/total:100):N1}% • {skipped:N0} skipped • {coverage}\n{path}");lastReport=watch.Elapsed;}
 try{using var insert=db.Prepare("INSERT OR IGNORE INTO hashes VALUES(?,?,?,?,?)");db.Exec("BEGIN");var sql="SELECT path,size,modified FROM eligible WHERE size IN (SELECT size FROM duplicate_sizes) ORDER BY size,path COLLATE NOCASE"+(candidateLimit>0?$" LIMIT {candidateLimit}":"");
 foreach(var r in db.Query(sql)){ct.ThrowIfCancellationRequested();var e=new Entry(r[0],long.Parse(r[1]),long.Parse(r[2]),"file");worker??=NativeWorkers.Start("--hash-worker");await worker.StandardInput.WriteLineAsync(JsonSerializer.Serialize(e));HashResult? hash=null;if(checkedFiles==0||watch.Elapsed-lastReport>TimeSpan.FromMilliseconds(180))Report(e.Path);
 while(true){if(watch.Elapsed-lastReport>TimeSpan.FromMilliseconds(180))Report(e.Path);string? line;using var deadline=CancellationTokenSource.CreateLinkedTokenSource(ct);deadline.CancelAfter(TimeSpan.FromSeconds(10));try{line=await worker.StandardOutput.ReadLineAsync(deadline.Token);}catch(OperationCanceledException)when(!ct.IsCancellationRequested){skipped++;Kill();break;}if(line==null){skipped++;Kill();break;}if(line.StartsWith("PROGRESS "))continue;hash=JsonSerializer.Deserialize<HashResult>(line);break;}
 checkedFiles++;if(hash!=null){if(hash.Error.Length>0)skipped++;else{hashed++;bytesHashed+=e.Size;insert.Text(1,hash.Hash);insert.Text(2,hash.Identity);insert.Text(3,e.Path);insert.Number(4,e.Size);insert.Number(5,e.Modified);insert.Execute();}}if(checkedFiles%1024==0)db.Exec("COMMIT; BEGIN");}
 db.Exec("COMMIT");ct.ThrowIfCancellationRequested();var totals=db.Query("SELECT COALESCE(SUM(size*(copies-1)),0),COUNT(*) FROM (SELECT size,COUNT(*) copies FROM hashes GROUP BY hash,size HAVING COUNT(*)>1)").First();summary?.Invoke(long.Parse(totals[0]),long.Parse(totals[1]));var result=new List<Entry>();foreach(var group in db.Query("SELECT hash,size,COUNT(*) FROM hashes GROUP BY hash,size HAVING COUNT(*)>1 ORDER BY size*(COUNT(*)-1) DESC")){bool first=true;foreach(var r in db.Query($"SELECT path,size,modified FROM hashes WHERE hash={Db.Q(group[0])} AND size={group[1]} ORDER BY path COLLATE NOCASE")){ct.ThrowIfCancellationRequested();result.Add(new Entry(r[0],long.Parse(r[1]),long.Parse(r[2]),"file",$"SHA-256 {group[0][..12]} • {(first?"suggested keeper":"verified copy")} • {skipped} unreadable/changed/timed-out files skipped"+(limited?" • Quick check: limited coverage":"")));first=false;if(result.Count>=500)break;}if(result.Count>=500)break;}
 metrics?.Invoke(new(available,total,hashed,skipped,bytesHashed,watch.Elapsed.TotalMilliseconds,limited));progress.Report($"Duplicate check complete • {coverage} • {hashed:N0} fully hashed • {skipped:N0} skipped • results capped at 500 rows"+(limited?" • More candidates remain; use Full check":""));return result;
 }catch{ct.ThrowIfCancellationRequested();throw;}finally{Kill();}
 }

}









